const reviewUsage = `-- name: ReviewUsage :many
SELECT
    benefit_package_id,
    COUNT(*) FILTER (
        WHERE
            status IN ('committed', 'releasing', 'reacquiring')
    ) AS committed,
    COUNT(*) FILTER (
        WHERE
            status = 'reserved'
    ) AS reserved
FROM
    benefit_package_review_reservations
WHERE
    tenant_id = $1
    AND workspace_id = $2
GROUP BY
    benefit_package_id
`

type ReviewUsageParams struct {
	TenantID    string
	WorkspaceID string
}

type ReviewUsageRow struct {
	BenefitPackageID string
	Committed        int64
	Reserved         int64
}

func (q *Queries) ReviewUsage(ctx context.Context, arg ReviewUsageParams) ([]ReviewUsageRow, error) {
	rows, err := q.db.Query(ctx, reviewUsage, arg.TenantID, arg.WorkspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReviewUsageRow{}
	for rows.Next() {
		var i ReviewUsageRow
		if err := rows.Scan(&i.BenefitPackageID, &i.Committed, &i.Reserved); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

